<?php declare(strict_types=1);
function annualSetupDatabase(PDO $db):array{
 $c=Kulturhus\Native\TestSupport::config();if(($c['owner']??'')!=='isolated-native-ci'||($c['label']??'')!=='native-balance-annual-setup-interface'||($c['host']??'')!=='127.0.0.1'||($c['port']??0)!==13371||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',$c['database']??'')||$db->query('SELECT DATABASE()')->fetchColumn()!==$c['database']||(int)$db->query('SELECT MAX(version)FROM schema_migrations')->fetchColumn()!==135)throw new RuntimeException('Exact own annual setup database required');return$c;
}
function annualSetupTargets(array $f):array{
 $parts=[];$args=[];if(count($f['data']['profiles'])!==8)throw new RuntimeException('Eight actual setup clubs required');foreach($f['data']['profiles']as$profile=>$data){$expected=in_array($profile,[1,3,6,8],true)?'initial':'carry';if($data['club']!=='annual-setup-ui-'.$profile||$data['scenario']!==$expected||$data['year']!==($expected==='initial'?2025:2026))throw new RuntimeException('Exact initial/carry club and year required');$parts[]='(club_id=? AND tax_year=?)';$args[]=$data['club'];$args[]=$data['year'];}return[implode(' OR ',$parts),$args];
}
function annualSetupFilter(array $f):callable{
 [$where,$args]=annualSetupTargets($f);return static fn(string$table):array=>match($table){'balance_years','balance_opening_corrections'=>[' WHERE NOT('.$where.')',$args],'audit_events'=>[' WHERE sequence<=?',[$f['data']['proof_baseline']['audit']]],default=>['',[]]};
}
function annualSetupRows(PDO $db,string $table,array $f):array{
 if(!in_array($table,['balance_years','balance_opening_corrections','audit_events'],true))throw new RuntimeException('Exact annual setup table required');$q=$db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$columns=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY'ORDER BY ORDINAL_POSITION");$q->execute([$table]);$keys=$q->fetchAll(PDO::FETCH_COLUMN);if(!$columns||!$keys)throw new RuntimeException('Actual setup columns and primary keys required');[$where,$args]=$table==='audit_events'?['sequence>?',[$f['data']['proof_baseline']['audit']]]:annualSetupTargets($f);$quote=static fn(string$v):string=>'`'.str_replace('`','``',$v).'`';$q=$db->prepare('SELECT '.implode(',',array_map($quote,$columns)).' FROM '.$quote($table).' WHERE '.$where.' ORDER BY '.implode(',',array_map($quote,$keys)));$q->execute($args);return$q->fetchAll(PDO::FETCH_ASSOC);
}
function annualSetupSnapshot(PDO $db,array $f,int $profile):array{
 annualSetupDatabase($db);$tables=array_values(array_diff($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN),['native_auth_sessions','native_auth_limits','native_language_preferences']));$out=['protected_sha256'=>ownOriginalDatabaseHash($db,$tables,annualSetupFilter($f)),'protected_tables'=>count($tables),'profile'=>$profile];foreach(['balance_years'=>'years','balance_opening_corrections'=>'opening_corrections','audit_events'=>'audits']as$table=>$key)$out[$key]=annualSetupRows($db,$table,$f);$data=$f['data']['profiles'][$profile];$ledger=new Kulturhus\Verein\BalanceLedger($db,'annualsetup-'.$profile.'-finance');$out['state']=$ledger->report($data['year']);$out['current_prior']=$data['scenario']==='carry'?$ledger->report(2025):null;$out['original_prior']=$data['scenario']==='carry'?$ledger->report(2025,true):null;return$out;
}
function annualSetupProof(array $f):void{
 $profile=$_SERVER['HTTP_X_OWNED_SOURCE_OUTCOME']??null;if(PHP_SAPI!=='cli-server'||($_SERVER['REQUEST_METHOD']??'')!=='GET'||!is_string($profile)||!preg_match('/\A[1-8]\z/D',$profile)||!is_string($_SERVER['HTTP_X_OWNED_ANNUAL_SETUP_PROOF']??null)||!hash_equals($f['data']['proof_nonce']??'',$_SERVER['HTTP_X_OWNED_ANNUAL_SETUP_PROOF'])){http_response_code(403);exit;}require_once dirname(__DIR__,2).'/src/bootstrap.php';require_once __DIR__.'/original-database-hash.php';$db=Kulturhus\Native\TestSupport::db();header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');echo json_encode(annualSetupSnapshot($db,$f,(int)$profile),JSON_THROW_ON_ERROR),PHP_EOL;
}
